/// Position of `ch` in [`KSX1001`], or `None` when the standard omits it.
pub fn ksx1001_index(ch: char) -> Option<usize> {
    let v = u16::try_from((ch as u32).checked_sub(0xac00)?).ok()?;
    KSX1001.binary_search(&v).ok()
}
